// Generate .cf-orbs/wrangler.jsonc from cf-orbs.config.jsonc. Users never edit the output.
// Paths are relative to the .cf-orbs/ directory that holds the generated file (see project.ts layout).
import { type CfOrbsConfig, orbImageKeys, workerConfigJson } from "./config.js";

export const COMPATIBILITY_DATE = "2026-10-30";
export const PROVIDER_CRON = "*/5 * * * *";
/** Durable Object classes the Worker exports. Names must match worker/src/index.ts. */
export const DO_CLASSES = ["OrbSession", "Registry", "ProviderHost"] as const;
/** Binding names the Worker reads from env. Must match worker/src/index.ts Env. */
export const DO_BINDINGS = { ORB: "OrbSession", REGISTRY: "Registry", PROVIDER: "ProviderHost" } as const;
/** Fields the durable_object scheduling policy rejects. Never emitted. */
export const FORBIDDEN_DO_CONTAINER_FIELDS = [
  "image",
  "instance_type",
  "max_instances",
  "rollout_step_percentage",
  "rollout_kind",
  "constraints",
];

export interface WranglerOptions {
  accountId?: string;
  /** Hash of the provider image inputs (project.ts providerBuild). Becomes CF_ORBS_PROVIDER_BUILD. */
  providerBuild?: string;
}

/** Dockerfile path for an orb image key, relative to .cf-orbs/. Key "orb" is image/Dockerfile; others image/<key>.Dockerfile. */
export function orbDockerfile(key: string): string {
  return key === "orb" ? "../image/Dockerfile" : `../image/${key}.Dockerfile`;
}

/** Container application names wrangler derives: <worker>-<class lowercase>. */
export function containerAppNames(workerName: string): string[] {
  return [`${workerName}-orbsession`, `${workerName}-providerhost`];
}

export function buildWranglerConfig(c: CfOrbsConfig, o: WranglerOptions = {}): Record<string, unknown> {
  const orbImages: Record<string, { dockerfile: string; build_context: string }> = {};
  for (const key of orbImageKeys(c))
    orbImages[key] = { dockerfile: orbDockerfile(key), build_context: "../image" };
  const orbContainer: Record<string, unknown> = {
    class_name: "OrbSession",
    scheduling_policy: "durable_object",
    images: orbImages,
  };
  if (c.debugSsh) orbContainer.ssh = { enabled: true };
  const cfg: Record<string, unknown> = {
    name: c.name,
    main: "worker/src/index.ts",
    compatibility_date: COMPATIBILITY_DATE,
    compatibility_flags: ["nodejs_compat"],
    // explicit, so wrangler does not warn: the control plane is on workers.dev; preview URLs are not used
    workers_dev: true,
    preview_urls: false,
    observability: { enabled: true },
    containers: [
      orbContainer,
      {
        class_name: "ProviderHost",
        scheduling_policy: "durable_object",
        // build context is .cf-orbs/ (mirrors the repo root) so provider/Dockerfile can COPY dispatch/dispatch.sh
        images: { provider: { dockerfile: "provider/Dockerfile", build_context: "." } },
      },
    ],
    durable_objects: {
      bindings: Object.entries(DO_BINDINGS).map(([name, class_name]) => ({ name, class_name })),
    },
    exports: Object.fromEntries(DO_CLASSES.map((k) => [k, { type: "durable-object", storage: "sqlite" }])),
    triggers: { crons: [PROVIDER_CRON] },
    vars: { CF_ORBS_CONFIG: workerConfigJson(c) },
  };
  if (o.accountId) cfg.account_id = o.accountId;
  if (o.providerBuild) (cfg.vars as Record<string, string>).CF_ORBS_PROVIDER_BUILD = o.providerBuild;
  return cfg;
}

export function renderWranglerJsonc(c: CfOrbsConfig, o: WranglerOptions = {}): string {
  const cfg = buildWranglerConfig(c, o);
  return `// Generated by cf-orbs from ../cf-orbs.config.jsonc. Do not edit: cf-orbs deploy overwrites it.\n${JSON.stringify(cfg, null, 2)}\n`;
}
